(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  let wy = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  wx += Math.sin(wx*0.08+t*0.5)*8+Math.cos(wy*0.06-t*0.4)*6;
  wy += Math.cos(wy*0.08-t*0.45)*8+Math.sin(wx*0.07+t*0.55)*6;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.7],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.5],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.8],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.6],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.9],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.4],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1,0.65],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75)*40,0.085,1.8,0.55]
  ];
  let aS=0,iS=0,mS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w1=Math.sin(d*f-t*sp),w2=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS+=w1*w; iS+=w2*w; mS+=Math.sin(d*f*1.3-t*sp*0.8+0.7)*w;
  }
  const act=aS/8,inh=iS/8,mod=mS/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const rd1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const lap=Math.sin(sx*0.2)*Math.sin(sy*0.2)+Math.sin((sx-sy)*0.15)*Math.cos((sx+sy)*0.12);
  const diffusion=Math.tanh((rd1+lap*0.6+mod*0.4)*1.8);
  const grain=Math.sin(sx*0.8+t*3)*Math.sin(sy*0.8-t*2.5)*0.08;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const blend=diffusion*0.6+cell*0.2+grain, v=blend*0.5+0.5;
  const pal=[[6,12,52],[12,48,82],[18,95,120],[28,148,138],[140,175,90],[210,185,60],[195,110,55],[155,50,60],[95,22,55],[45,15,65],[6,12,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(diffusion*Math.PI)*0.18;
  const edge=Math.abs(diffusion)>0.65?1.18:1.0;
  const glow=Math.max(0,diffusion)*0.12;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*180)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*120)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*200)|0)
  ];
}
